    private static TarotCard Card(
        int number,
        string name,
        string arcana,
        string? suit,
        string uprightMeaning,
        string reversedMeaning)
    {
        return new TarotCard
        {
            Id = Guid.Parse($"00000000-0000-0000-0000-{number:000000000000}"),
            Name = name,
            Arcana = arcana,
            Suit = suit,
            UprightMeaning = uprightMeaning,
            ReversedMeaning = reversedMeaning
        };
    }
